    "description": "据路透社等多家媒体17日报道，考虑到隐私和安全等因素，澳大利亚拟禁止在联邦政府工作场所使用配备摄像头的智能眼镜。此外，澳政府还将召集包括微软、澳大利亚联邦银行、澳大利亚电信等多家在澳大型企业举行圆桌会议，围绕工作场所人工智能的使用规范进行磋商。（新华社）",
    "content": "据路透社等多家媒体17日报道，考虑到隐私和安全等因素，澳大利亚拟禁止在联邦政府工作场所使用配备摄像头的智能眼镜。此外，澳政府还将召集包括微软、澳大利亚联邦银行、澳大利亚电信等多家在澳大型企业举行圆桌会议，围绕工作场所人工智能的使用规范进行磋商。（新华社）"
