    "description": "甘肃省环县曲子镇西沟村，一座座标准化羊舍错落分布在黄土沟壑之间。初秋时节，记者走进这个小村庄，养殖场、农户院落里，“咩咩”羊叫声此起彼伏，一只只肉羊膘肥体壮。 在西沟村一处养殖场，工作人员给羊投喂饲料。（环县融媒体中心供图） 西沟村有一处占地15亩的肉羊营养中心，仓库中高高码放着一堆堆不同颜色的饲料袋。“绿色的给羔羊，黄色的给育肥羊，红色的给母羊，不同包装代表不同配料。这里每天加工8吨配方饲料，供应全村310户养殖户。”西沟村党总支书记…",
    "content": "甘肃省环县曲子镇西沟村，一座座标准化羊舍错落分布在黄土沟壑之间。初秋时节，记者走进这个小村庄，养殖场、农户院落里，“咩咩”羊叫声此起彼伏，一只只肉羊膘肥体壮。 在西沟村一处养殖场，工作人员给羊投喂饲料。（环县融媒体中心供图） 西沟村有一处占地15亩的肉羊营养中心，仓库中高高码放着一堆堆不同颜色的饲料袋。“绿色的给羔羊，黄色的给育肥羊，红色的给母羊，不同包装代表不同配料。这里每天加工8吨配方饲料，供应全村310户养殖户。”西沟村党总支书记刘小兵指着分色包装的饲料袋说。 10余年前，当地群众称西沟村为全镇“面积最大、条…"
