    "description": "本人 35 岁 前段时间午饭后偶尔肚子不舒服(想拉肚子那种不适)，经常拉稀 后来特意留意三餐尽可能规律干净，早上包子鸡蛋稀饭，午饭基本老乡鸡，晚饭也尽可能保证干净卫生，但偶尔还会肚子不舒服想拉稀，一般刚拉出来的比较正常，后面就是稀的，偶尔也会拉成形大便 除了成不成形的问题，也留意颜色，大部分偏褐色或棕色，没有出血情况 想知道大家都这样吗？我这情况有没有必要去做检查，甚至做胃肠镜？",
