    "pub_date": "2026-09-18 17:17:47",
    "author": "",
    "description": "中国银行保险资产管理业协会最新调研数据显示，2025年，37家保险机构以外汇形式开展境外投资余额901.29亿美元，同比增长13.9%，增速创近5年新高。截至2025年末，行业境外投资收益余额45.15亿美元，财务收益率为5%；2025年，共计127家保险机构开展港股通投资业务，2025年末港股通投资余额为1.61万亿元，同比增长112%，财务收益率为11.9%。（财联社）",
