    "content": "它就是—— 留香珠。 如果你不太熟悉这个名字，那你可能也在各种社交平台上见过这种产品，或者生活中其实已经用过了，它长这样—— 图片来源：小红书 留香珠属于近几年开始火起来的一种“洗衣伴侣”， 和洗衣液、洗衣凝珠、柔顺剂等不一样，留香珠可以没有清洁、柔顺效果，它的目的就是为织物增加香味的，属于近些年的一种新兴网红产品。 清新又甜润的香气充斥了所有感官！ 洗衣服被子的时候加点它，味道持久，仿佛回到了在妈妈肚子里，特别安心 隔着屏幕看到这些描述，小女孩大女孩都很扛住诱惑吧，毕竟，谁不希望自己从头到脚、到被窝都是香香的呢！…"
