    "content": "金秋9月，成都中医药大学药用植物园内，一堂沉浸式本草认知实践课在这里展开：140多名护理学院研究生跟随老师辨识药用植物，将课本上的药材知识与实物一一印证。 园林中的生动一课，正是新中国中医药高等教育蓬勃发展的缩影。 从口传心授到院校育人，70年来，中医药人才培养体系日臻完善。越来越多青年学子接过岐黄薪火，为中医药传承创新发展注入蓬勃的青春力量。 2026年9月1日，在成都中医药大学药用植物园，学生们跟随老师辨识药用植物。（成都中医药大学供图） 广州中医药大学博士生李梓媛学习中医的初心，源自中学时一次触动内心的经历：…"
