    "title": "关注城市更新丨住房城乡建设部：四方面措施建设改造城市地下管网",
    "link": "http://www.news.cn/20260918/31a2e86066ec474e8be8ee8a41029bd2/c.html",
    "pub_date": "2026-09-18 17:09:45",
    "author": "王优玲",
    "description": "新华社北京9月18日电（记者王优玲）住房城乡建设部新闻发言人、副部长陈绍旺18日在国新办“开局起步‘十五五’”系列主题新闻发布会上表示，“十五五”时期，我国将建设改造约77万公里城市地下管网，加快推进城市排水防涝设施补短板，持续推进城市生命线安全工程建设，不断提高抵御灾害风险的能力。 城市地下管网主要包括燃气、供水、排水、污水、供热等管网和综合管廊，它们是城市的“血管”和“神经”，是现代化基础设施网络体系的重要组成部分。据介绍，为完成好…",
    "content": "新华社北京9月18日电（记者王优玲）住房城乡建设部新闻发言人、副部长陈绍旺18日在国新办“开局起步‘十五五’”系列主题新闻发布会上表示，“十五五”时期，我国将建设改造约77万公里城市地下管网，加快推进城市排水防涝设施补短板，持续推进城市生命线安全工程建设，不断提高抵御灾害风险的能力。 城市地下管网主要包括燃气、供水、排水、污水、供热等管网和综合管廊，它们是城市的“血管”和“神经”，是现代化基础设施网络体系的重要组成部分。据介绍，为完成好城市地下管网建设改造任务，住房城乡建设部将采取四方面措施： 着眼“建得好”，抓系…"
