    "content": "拼假连休撬动超长假期，今年中秋国庆出行市场热度持续攀升。 9月18日，据第三方出行平台“航班管家”数据显示，2026年中秋国庆期间（9月25日至10月7日）民航预计执行客运航班总量达21.9万班次，日均超1.68万班次，同比增长2%。其中，国内（含地区）航班量预计同比增长2%、国际增长2.3%。旅客运输量预计达3102.3万人次（仅含境内航司承运量），日均同比增长3.1%。其中，国内（含地区）同比增长3.1%、国际增长2.9%。 今年中秋、国庆假期仅隔3天，旅客“请3休13”即可打造全年最长出游窗口。近期，多地高校…"
