    "content": "9月18日，国新办举行“开局起步‘十五五’”系列主题新闻发布会，住房城乡建设部有关负责人介绍，提升人民群众居住水平关键是建设“好房子”。建设什么样的好房子？安全、舒适、绿色、智慧。怎样建设好房子？从好标准、好设计、好材料、好建造、好运维全链条全生命周期推进。 事实上，去年5月1日起正式施行的《住宅项目规范》已对住宅的防水、隔声、结构安全等方面作了系统升级，“好房子”有了明确标准；去年底，住建部又发布《关于提升住房品质的意见》，明确从完善住房建设标准、提升建筑设计水平、推广应用好材料等八个重点任务入手，进一步适应人民…"
