    "title": "7月至今7家电商平台拦截违规充电宝商品3.7万件",
    "link": "http://www.news.cn/20260918/211db7c7926b4d9ea9c64fd2dc4cb7d8/c.html",
    "pub_date": "2026-09-18 16:33:51",
    "author": "李倩薇,王悦阳",
    "description": "新华社北京9月18日电（记者李倩薇、王悦阳）记者18日从市场监管总局召开的强化质量认证监管专题新闻发布会上了解到，针对当前市场上仍然存在的生产、销售无CCC认证充电宝的情况，今年7月至9月，市场监管总局部署开展无CCC认证充电宝集中整治行动。行动开展至今，7家主要电商平台已开展联网核查376.3万次，拦截违规充电宝商品3.7万件，督促下架或拦截上架的店铺3831家。",
    "content": "新华社北京9月18日电（记者李倩薇、王悦阳）记者18日从市场监管总局召开的强化质量认证监管专题新闻发布会上了解到，针对当前市场上仍然存在的生产、销售无CCC认证充电宝的情况，今年7月至9月，市场监管总局部署开展无CCC认证充电宝集中整治行动。行动开展至今，7家主要电商平台已开展联网核查376.3万次，拦截违规充电宝商品3.7万件，督促下架或拦截上架的店铺3831家。"
