    "content": "大联大控股宣布，其旗下诠鼎携手意法半导体（ST）推出人形机器人执行器全链路方案。 图示1-大联大诠鼎携手ST推出的人形机器人系统级技术布局框架图 随着人形机器人从实验室走向规模化量产，执行器作为决定机器人灵活度、负载能力与动态响应的核心硬件，正面临小型化、高精度、低功耗与高可靠性的多重技术挑战。在此背景下，大联大诠鼎携手ST推出人形机器人执行器全链路方案，涵盖基于STM32的电机控制、MOSFET / 氮化镓（GaN）功率器件、STDRIVE栅极驱动器、STSPIN封装系统级电机驱动器，同时配套通信、惯性测量单元、…"
