    "description": "新华社北京9月18日电 记者18日从中国气象局了解到，中国气象局近日制定了《升放气球安全领域重大事故隐患判定规定》和《防雷安全领域重大事故隐患判定规定》，并对《防雷减灾管理办法》进行了修订，推动升放气球和防雷安全管理领域从重审批向强监管、优服务转变。这三个部门规章自今年11月1日起施行。 《升放气球安全领域重大事故隐患判定规定》明确生产经营单位判定为升放气球领域重大事故隐患的8项判定规定：未取得《升放气球资质证》却从事升放气球活动的；未…",
    "content": "新华社北京9月18日电 记者18日从中国气象局了解到，中国气象局近日制定了《升放气球安全领域重大事故隐患判定规定》和《防雷安全领域重大事故隐患判定规定》，并对《防雷减灾管理办法》进行了修订，推动升放气球和防雷安全管理领域从重审批向强监管、优服务转变。这三个部门规章自今年11月1日起施行。 《升放气球安全领域重大事故隐患判定规定》明确生产经营单位判定为升放气球领域重大事故隐患的8项判定规定：未取得《升放气球资质证》却从事升放气球活动的；未经批准擅自升放气球的；未按照批准的申请升放气球的；在规定的禁止区域内升放气球的；…"
