    "content": "新华社北京9月18日电 世界气象组织日前发布公报称，厄尔尼诺事件已确认出现，预计将在数月内发展为超强厄尔尼诺事件。据英国《卫报》18日报道，亚洲多国政府正积极采取措施，应对严重厄尔尼诺现象所致干旱、野火、台风和洪水。 韩国今年夏季遭遇持续高温，土地变得如同烤箱，有民众称土豆在地里“焖熟”。韩国高温预警系统原本只有两级，由于极端天气越来越频繁，该系统新设最高级别“高温重大警报”，并于6月1日起生效。据报道，这是韩国气象部门18年来首次更新高温预警系统，新设“高温重大警报”会在体感温度达38摄氏度时触发官方发布指导意见…"
