    "content": "新华社吉隆坡9月18日电 记者手记丨从“嫦娥”到AI 马来西亚学生感知中国科技创新 新华社记者袁睿 何光海 提起“嫦娥”，很多马来西亚学生心中的答案或许不止一个。 中秋将至，中国驻马来西亚大使馆邀请近80名当地学生走进使馆，体验中国传统文化，感知中国发展脉搏。“月饼！”“灯笼！”“嫦娥奔月！”对中国文化有所了解的学生们纷纷谈及各自对于中秋的印象。 “还有嫦娥探测器！”一名学生的回答将大家的视角引向更广阔的领域。活动现场，学生们了解到中国的探月工程，得知“嫦娥”不仅是神话人物。 生活在科技创新时代的青少年，对前沿科技…"
