    "content": "新华社银川9月18日电（记者谢建雯、杨稳玺）近日，宁夏回族自治区人力资源和社会保障厅印发了《宁夏回族自治区深化产教评技能生态链建设工作方案》，同步部署首批产教评技能生态链遴选申报工作，构建链主引领、链员协同、校企联动、评价贯通、激励到位的技能人才发展新格局，打通产业、教育培训、评价融通壁垒，全面推进宁夏产教评技能生态链建设。 据介绍，产教评技能生态链以服务重点产业为核心，打造以行业企业为主体，普通高校、职业（技工）院校、培训机构、技能评价机构、人力资源服务机构、行业协会等共同参与的技能人才共同体，推动“产”出岗位标…"
