    "author": "周圆,戴小河,李倩薇",
    "description": "新华社北京9月18日电（记者周圆、戴小河）工业和信息化部等十部门18日公布《医药工业发展“十五五”规划》，提出到2030年，生物医药研发应用稳居世界前列，创新驱动效能充分释放，重点领域关键核心技术实现系统性突破。生物医药产业加速成为国家新兴支柱产业，持续守护增进人民生命健康福祉。 医药工业是关系国计民生和国家安全的战略性新兴产业。“十五五”时期是我国医药产业结构调整、创新驱动转型、全球影响力提升的重要机遇期。规划明确，构筑韧性安全根基，…",
    "content": "新华社北京9月18日电（记者周圆、戴小河）工业和信息化部等十部门18日公布《医药工业发展“十五五”规划》，提出到2030年，生物医药研发应用稳居世界前列，创新驱动效能充分释放，重点领域关键核心技术实现系统性突破。生物医药产业加速成为国家新兴支柱产业，持续守护增进人民生命健康福祉。 医药工业是关系国计民生和国家安全的战略性新兴产业。“十五五”时期是我国医药产业结构调整、创新驱动转型、全球影响力提升的重要机遇期。规划明确，构筑韧性安全根基，深化数智融合赋能，提高普惠可及水平，拓展开放互利合作，为全方位满足全生命周期健康…"
